from pathlib import Path
import hashlib

def patch(name, base, edits, expected):
    p=Path(name)
    data=p.read_bytes()
    assert hashlib.sha256(data).hexdigest()==base, name + ': base mismatch'
    lines=data.decode().splitlines(keepends=True)
    for start,count,replacement in reversed(edits):
        lines[start:start+count]=replacement.splitlines(keepends=True)
    data=''.join(lines).encode()
    assert hashlib.sha256(data).hexdigest()==expected, name + ': output mismatch'
    p.write_bytes(data)

